# main.tf
terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

provider "docker" {
  host = "tcp://localhost:2376"

  # TLS 配置 (生产环境必须)
  ca_material   = file("${path.module}/certs/ca.pem")
  cert_material = file("${path.module}/certs/cert.pem")
  key_material  = file("${path.module}/certs/key.pem")
}

# 网络配置
resource "docker_network" "app_network" {
  name   = "app-network"
  driver = "overlay"

  ipam_config {
    subnet = "172.20.0.0/16"
  }
}

# 镜像构建
resource "docker_image" "app" {
  name = "myapp:${var.image_tag}"

  build {
    context = "."
    dockerfile = "Dockerfile.prod"
    tag    = ["myapp:${var.image_tag}", "myapp:latest"]

    build_arg = {
      BUILD_DATE      = timestamp()
      VCS_REF         = var.git_commit
      VERSION         = var.app_version
    }
  }
}

# 服务部署
resource "docker_service" "app" {
  name = "app-service"

  task_spec {
    container_spec {
      image = docker_image.app.name

      env = {
        ENVIRONMENT = var.environment
        DATABASE_URL = var.database_url
        REDIS_URL    = var.redis_url
      }

      mounts {
        target = "/app/logs"
        source = "app-logs"
        type   = "volume"
      }
    }

    networks_advanced {
      name = docker_network.app_network.name
    }

    resources {
      limits {
        memory_bytes = 536870912  # 512MB
        nano_cpus    = 500000000  # 0.5 CPU
      }

      reservation {
        memory_bytes = 268435456  # 256MB
        nano_cpus    = 250000000  # 0.25 CPU
      }
    }
  }

  mode {
    replicated {
      replicas = var.replica_count
    }
  }

  update_config {
    parallelism     = 1
    delay           = "10s"
    failure_action  = "rollback"
    monitor         = "30s"
    max_failure_ratio = "0.3"
  }

  rollback_config {
    parallelism = 1
    delay       = "10s"
  }

  endpoint_spec {
    ports {
      target_port    = 3000
      published_port = 80
      protocol       = "tcp"
      publish_mode   = "ingress"
    }
  }
}

# variables.tf
variable "environment" {
  description = "部署环境"
  type        = string
  default     = "dev"
}

variable "image_tag" {
  description = "镜像标签"
  type        = string
}

variable "replica_count" {
  description = "副本数量"
  type        = number
  default     = 1
}

variable "database_url" {
  description = "数据库连接字符串"
  type        = string
  sensitive   = true
}

variable "redis_url" {
  description = "Redis连接字符串"
  type        = string
  sensitive   = true
}

# outputs.tf
output "service_endpoint" {
  description = "服务访问地址"
  value       = "http://${docker_service.app.endpoint_spec[0].ports[0].published_port}"
}

output "service_name" {
  description = "服务名称"
  value       = docker_service.app.name
}

// app-config.ctmpl
DATABASE_URL=postgresql://{{ with secret "database/creds/app" }}{{ .Data.username }}:{{ .Data.password }}@postgres:5432/app{{ end }}
REDIS_URL=redis://{{ with secret "redis/creds/app" }}{{ .Data.username }}:{{ .Data.password }}@redis:6379{{ end }}
API_KEY={{ with secret "app/api-key" }}{{ .Data.key }}{{ end }}
JWT_SECRET={{ with secret "app/jwt-secret" }}{{ .Data.secret }}{{ end }}
LOG_LEVEL={{ env "LOG_LEVEL" | default "info" }}

// 配置监听和热更新
package main

import (
    "context"
    "fmt"
    "log"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/hashicorp/consul/api"
)

type ConfigManager struct {
    client     *api.Client
    configPath string
    watcher    chan struct{}
}

func NewConfigManager(address, configPath string) (*ConfigManager, error) {
    config := api.DefaultConfig()
    config.Address = address

    client, err := api.NewClient(config)
    if err != nil {
        return nil, err
    }

    return &ConfigManager{
        client:     client,
        configPath: configPath,
        watcher:    make(chan struct{}),
    }, nil
}

func (cm *ConfigManager) WatchConfig(ctx context.Context) {
    ticker := time.NewTicker(30 * time.Second)
    defer ticker.Stop()

    for {
        select {
        case <-ticker.C:
            cm.updateConfig()
        case <-ctx.Done():
            return
        }
    }
}

func (cm *ConfigManager) updateConfig() {
    kv := cm.client.KV()

    // 获取配置
    pair, _, err := kv.Get(cm.configPath, nil)
    if err != nil {
        log.Printf("Failed to get config: %v", err)
        return
    }

    if pair == nil {
        log.Println("Config not found")
        return
    }

    // 更新应用配置
    // 这里实现具体的配置更新逻辑
    log.Println("Configuration updated successfully")

    // 通知应用重新加载配置
    cm.watcher <- struct{}{}
}

func main() {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    // 处理信号
    sigChan := make(chan os.Signal, 1)
    signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

    // 初始化配置管理器
    cm, err := NewConfigManager("consul:8500", "app/config")
    if err != nil {
        log.Fatal(err)
    }

    // 启动配置监听
    go cm.WatchConfig(ctx)

    // 应用主循环
    for {
        select {
        case <-cm.watcher:
            fmt.Println("Reloading application configuration...")
            // 重新加载应用配置的逻辑

        case <-sigChan:
            fmt.Println("Shutting down...")
            return
        }
    }
}
